def period_from_year(y):
    if y < 1400: return "Ancient / Medieval"
    elif y < 1500: return "Early Renaissance"
    elif y < 1600: return "High Renaissance / Mannerism"
    elif y < 1700: return "Baroque"
    elif y < 1800: return "Rococo / Neoclassicism"
    elif y < 1850: return "Romanticism"
    elif y < 1900: return "Realism / Impressionism"
    elif y < 1945: return "Modernism"
    elif y < 1980: return "Post-War / Contemporary"
    else: return "Contemporary"

