    ("Qi Baishi: Shrimp", "Qi Baishi", 1940, "Ink on paper", "Republican Period / Chinese Modern", ["literati","ink","animals","loose","expressive"], ["shrimp","ink wash","loose brushwork","transparent","movement"], ["ink grey","transparent washes","white paper"], "Various collections", "Shrimp rendered in pure ink wash with extraordinary transparency and a sense of liquid movement.", "Qi Baishi is the best-loved Chinese painter of the 20th century. His shrimp achieved perfect balance between observation and expressive mark-making.", "male", "Chinese"),
    ("Ren Xiong: Self-Portrait", "Ren Xiong", 1850, "Ink and color on paper", "Qing Dynasty / Chinese", ["self-portrait","unusual","confrontational","late Qing","melancholic"], ["self-portrait","dramatic pose","exposed body","direct gaze"], ["ink blue","flesh","red","dramatic"], "Palace Museum, Beijing", "A dramatic self-portrait in which Ren Xiong confronts the viewer in a theatrical, melancholic pose.", "Unique in Chinese art history for its theatrical self-exposure and psychological directness. Very unusual in the context of Chinese portraiture.", "male", "Chinese"),
    ("Fu Baoshi: The Goddess of the Luo River", "Fu Baoshi", 1944, "Ink and color on paper", "Republican / Chinese Modern", ["ink wash","lyrical","mythological","atmospheric","figure"], ["water goddess","mist","river","mythology","atmospheric"], ["blue ink","mist","atmospheric","lyrical"], "Various collections", "The water goddess of the Luo River floats in atmospheric mist — lyrical fusion of classical poetry and modern ink technique.", "Fu Baoshi developed a unique ink-wash style that combined Tang dynasty poetry with modern expressive technique.", "male", "Chinese"),
