    ("Raja Ravi Varma: Shakuntala Looking for Bees", "Raja Ravi Varma", 1894, "Oil on canvas", "Indian Academic Realism", ["academic","mythological","indian","realistic","romantic"], ["Shakuntala","writing","bees","kalidasa","india"], ["green foliage","cream dress","warm skin","romantic"], "Sri Chitra Art Gallery, Thiruvananthapuram", "Shakuntala writes her love letter with a sharp nail, distracted by bees attracted to her flower garland — from Kalidasa's play.", "Ravi Varma was the first Indian artist to use oil paint in a European academic style. His mythological prints were distributed across India and defined popular Hindu iconography.", "male", "Indian"),
    ("Gaganendranath Tagore: Dwarf (Baul Singer)", "Gaganendranath Tagore", 1922, "Watercolor and gouache", "Bengali Renaissance / Indian", ["modernist","cubist influenced","bengali","social commentary","caricature"], ["baul singer","cubist distortion","bengali culture","social satire"], ["dark colors","cubist distortion","social commentary"], "Rabindra Bharati Society, Kolkata", "A Baul (wandering mystic singer) depicted with cubist distortion and social satire.", "Gaganendranath was the first Indian Cubist — absorbing Cubism from European magazines and applying it to Bengali folk culture and social commentary.", "male", "Indian"),
    ("Jamini Roy: The Three Maries", "Jamini Roy", 1940, "Casein on cardboard", "Indian Modernism / Bengal", ["flat color","bengali folk","bold outline","modern","simplified"], ["three women","folk art style","simplified","bold outline","Indian"], ["terracotta","cream","black bold outline","Indian ochre"], "Various collections", "Three women in a simplified, folk-art-influenced style with bold outlines and flat color.", "Roy rejected European academism and based his style on Kalighat pat painting — a Bengali folk tradition. His synthesis created a uniquely Indian modernism.", "male", "Indian"),
