    # ADDITIONAL EUROPEAN MODERN
    ("Mondrian: Tableau I", "Piet Mondrian", 1921, "Oil on canvas", "De Stijl / Dutch", ["de stijl","grid","primary colors","black lines","minimal"], ["grid","red rectangle","blue small","yellow small","black lines"], ["red","blue","yellow","black lines","white"], "Gemeentemuseum Den Haag", "A grid of black lines divides the canvas with one large red rectangle — the classic Mondrian composition.", "Mondrian's Tableau series established the format that defined De Stijl for the world. The asymmetric grid creates tension through pure geometric means.", "male", "Dutch"),
    ("Kupka: Amorpha, Fugue in Two Colors", "Frantisek Kupka", 1912, "Oil on canvas", "Orphism / Czech", ["abstract","circular motion","orphism","color","cosmic"], ["two interlocking circles","color abstraction","cosmic","fugue"], ["vivid red","dark blue","circular forms"], "National Gallery, Prague", "Two interlocking forms — one red, one dark — spiral in a cosmic fugue of pure color abstraction.", "Kupka independently arrived at pure abstraction simultaneously with Kandinsky. His musical-cosmological approach is unique in early abstraction.", "male", "Czech"),
    ("Léger: Three Women (Le Grand Déjeuner)", "Fernand Léger", 1921, "Oil on canvas", "Purism / Cubism", ["cubist","figurative","mechanical","monumental","classical"], ["three women","nude reclining","mechanical forms","classical","monumental"], ["grey","cream","classical architecture","mechanical flesh"], "Museum of Modern Art, MoMA", "Three large nude women in a precise, monumental arrangement — their bodies as smooth and mechanical as the objects around them.", "Léger's post-WWI classicism treats the female nude with the same formal dignity as a machine — neither more nor less. Pure form.", "male", "French"),
    ("Le Corbusier: Still Life (Purism)", "Le Corbusier (Charles-Édouard Jeanneret)", 1920, "Oil on canvas", "Purism / Swiss-French", ["purist","still life","geometric","bottles","precise"], ["bottles","glasses","table","geometric precision","purism"], ["cream","grey","precise geometric","table still life"], "Fondation Le Corbusier, Paris", "Bottles, glasses, and a pipe arranged with architectural precision on a table — the manifesto of Purist painting.", "Le Corbusier and Ozenfant codified Purism as a reaction to what they saw as Cubism's decorative excess. Painting as architecture of the visible world.", "male", "Swiss"),
    ("Chirico: The Soothsayer's Recompense", "Giorgio de Chirico", 1913, "Oil on canvas", "Metaphysical Art / Italian", ["metaphysical","silence","train","shadow","clock"], ["train","palm tree","classical arcade","shadow","afternoon silence"], ["warm ochre","long shadow","yellow sky","deserted"], "Philadelphia Museum of Art", "A steam train passes behind a classical arcade where a reclining figure lies — afternoon silence amplified by long shadows.", "De Chirico's metaphysical paintings made the familiar strange by silence, long shadows, and the juxtaposition of ancient and modern.", "male", "Italian-Greek"),
    ("Modigliani: Head (Tête)", "Amedeo Modigliani", 1911, "Limestone sculpture", "Modernism / Italian", ["sculpture","elongated","carved","serene","archaic"], ["elongated head","closed eyes","limestone","archaic","serene"], ["pale limestone","carved surface"], "Tate Modern, London", "An elongated limestone head with closed eyes and a simplified oval form — the carved equivalent of his painted faces.", "Modigliani carved these heads under Brancusi's influence. He wanted to create a 'temple of sculpture' but they were rejected as too extreme.", "male", "Italian"),
    ("Brancusi: Bird in Space", "Constantin Brancusi", 1928, "Bronze (polished)", "Modernism / Romanian", ["sculpture","polished bronze","soaring","abstract","form"], ["bird form","vertical","polished bronze","soaring","pure form"], ["mirror polished bronze","vertical form"], "Museum of Modern Art, MoMA", "A vertical form of polished bronze — the pure essence of flight rather than the image of a bird.", "When Brancusi exported this to the US in 1926, customs refused to classify it as art and taxed it as metal. The case, won by Brancusi, defined modern art legally.", "male", "Romanian"),
    ("Brancusi: The Kiss", "Constantin Brancusi", 1916, "Limestone", "Modernism / Romanian", ["sculpture","geometric","couple","minimal","kiss"], ["two faces","merging forms","geometric","minimal","embrace"], ["rough limestone","carved texture"], "Philadelphia Museum of Art", "Two simplified faces merge into a single geometric block — a kiss reduced to pure essential form.", "Brancusi's radical simplification — two human beings reduced to a cube divided by a line — asks what the essential form of love is.", "male", "Romanian"),
